  function updateTrackKeyboardPalette(){const el=document.getElementById('trackKeyboardPalette');if(!el)return;const show=trackKeyboardMode&&selected===37&&!trackTemplatePreview;el.classList.toggle('hidden',!show);if(!show)return;el.innerHTML=TRACK_SHAPES.map((shape,i)=>`<button class="track-key-item ${trackShapeMode===i?'active':''}" data-track-key-index="${i}" title="${trackShortcutLabel(i)} · ${TRACK_LABELS[i]} ${TRACK_SIZES[i]}"><span class="track-key-badge">${trackShortcutLabel(i)}</span>${trackIconSvg(shape)}<span class="track-key-name">${TRACK_LABELS[i]}</span></button>`).join('');}
  function chooseTrackType(index){trackShapeMode=Math.max(0,Math.min(TRACK_SHAPES.length-1,Number(index)||0));select(37);updateTrackModeHud();closeTrackPanel();toast(`已选择 ${TRACK_LABELS[trackShapeMode]} ${TRACK_SIZES[trackShapeMode]}`);}
  function chooseTrackShortcut(code,shifted=false){const slot=code==='Digit0'?10:Number(code.slice(5)),index=(shifted?10:0)+slot-1;if(!Number.isInteger(index)||index<0||index>=TRACK_SHAPES.length){toast('第二组轨道使用 Shift+1 到 Shift+9');return false;}trackShapeMode=index;select(37);updateTrackModeHud();toast(`⌨ ${trackShortcutLabel(index)} · ${TRACK_LABELS[index]} ${TRACK_SIZES[index]}`);saveGame();return true;}
