  function trackPlacementPreview(x,y,z,shape=TRACK_SHAPES[trackShapeMode],baseRot=trackRotationFromYaw()){const directY=(shape==='ramp'||shape==='rampcurve')&&rampRiseMode===false?y-1:y,direct={id:0,x,y:directY,z,rot:baseRot,shape,branch:false,rampRise:rampRiseMode,snapped:false,connections:0};if(!trackPieces.length)return direct;let best=null;const ys=(shape==='ramp'||shape==='rampcurve')?[y,y-1]:[y];for(const py of ys)for(let ax=x-2;ax<=x+2;ax++)for(let az=z-2;az<=z+2;az++)for(let rot=0;rot<4;rot++){const t={id:0,x:ax,y:py,z:az,rot,shape,branch:false,rampRise:rampRiseMode},cells=trackCells(t);if(!cells.some(c=>c.x===x&&c.y===y&&c.z===z)||cells.some(c=>!insideWorld(c.x,c.z)||c.y>MAX_BUILD_HEIGHT||c.y<MIN_BUILD_HEIGHT||get(c.x,c.y,c.z)))continue;let links=0;for(const p of trackPorts(t)){const row=trackPortIndex.get(trackPortKey(p));if(row?.some(v=>trackPorts(v.piece)[v.index]?.dir===(p.dir+2)%4))links++;}if(!links)continue;const c=trackCenter(t),turn=Math.min((rot-baseRot+4)%4,(baseRot-rot+4)%4),score=links*100-Math.hypot(c.x-(x+.5),c.z-(z+.5))-turn*.02;if(!best||score>best.score)best={...t,snapped:true,connections:links,score};}return best||direct;}
