  function interactTrack(t){if(!canNetworkEdit()){toast('主机暂时关闭了轨道控制权限');return;}if(!t)return;if(t.shape==='switch'){t.branch=!t.branch;rebuildMesh();toast(t.branch?'岔道已拨向弯道':'岔道已拨向直行');tone(t.branch?560:420,.07,'square');saveGame();return;}if(t.shape==='turntable'){if(trackPieceBusy(t)){toast('列车或车厢正在旋转轨上，暂时不能转向');tone(180,.06,'square');return;}t.turntableExit=(turntableSelectedExit(t)+1)%4;t.turntableAxis=t.turntableExit%2;trackNetworkCache=null;rebuildMesh();toast(`旋转轨当前出口：${turntableDirectionLabel(t)} · 再按E继续旋转`);tone(470+t.turntableExit*55,.09,'square');saveGame();return;}if(t.shape==='signal'){t.signalMode=t.signalMode===0?-1:t.signalMode===-1?1:0;t.signalGreen=t.signalMode!==-1;rebuildMesh();const autoGreen=signalDisplayGreen(t);toast(t.signalMode===0?`信号灯：自动模式 · 当前${autoGreen?'绿灯':'红灯'}`:t.signalMode===1?'信号灯：强制绿灯':'信号灯：强制红灯');tone(autoGreen?660:240,.09,'sine');saveGame();return;}if(t.shape==='station'){t.stationStop=t.stationStop===false;rebuildMesh();toast(t.stationStop?'车站已开启自动停靠':'车站已改为直接通过');tone(t.stationStop?580:360,.08,'sine');saveGame();return;}if(t.shape==='power'){t.powerMode=t.powerMode===1?-1:t.powerMode===-1?0:1;rebuildMesh();toast(t.powerMode===1?'动力轨：加速':t.powerMode===-1?'动力轨：制动':'动力轨：关闭');tone(t.powerMode===1?720:t.powerMode===-1?260:400,.08,'square');saveGame();return;}if(t.shape==='lantern'){t.trackLampOn=t.trackLampOn===false;rebuildMesh();toast(t.trackLampOn?'灯光轨已点亮':'灯光轨已熄灭');tone(t.trackLampOn?640:220,.09,'sine');saveGame();return;}if(t.shape==='crossing'){t.crossingMode=t.crossingMode===0?-1:t.crossingMode===-1?1:0;toast(t.crossingMode===0?'道口：自动感应':t.crossingMode===-1?'道口：强制关闭':'道口：强制打开');tone(t.crossingMode===-1?260:t.crossingMode===1?620:440,.08,'square');saveGame();return;}if(t.shape==='oneway'){t.oneWayForward=t.oneWayForward===false;rebuildMesh();toast(`单向轨方向已反转 · ${t.oneWayForward?'正向':'反向'}`);tone(520,.08,'square');saveGame();return;}if(t.shape==='drawbridge'){if(!t.drawbridgeOpen&&drawbridgeBusy(t)){toast('列车或客车厢正在桥上，不能升起');return;}t.drawbridgeOpen=!t.drawbridgeOpen;toast(t.drawbridgeOpen?'升降桥正在升起 · 轨道暂停通行':'升降桥正在放下 · 完全闭合后恢复通行');tone(t.drawbridgeOpen?420:260,.12,'square');saveGame();return;}if(t.shape==='detector'){t.detectorMode=((Number(t.detectorMode)||0)+1)%4;rebuildMesh();const automatic=t.detectorMode===2||t.detectorMode===3;toast(`感应轨：${detectorModeLabel(t)}${automatic?` · ${detectorTargetText(t)} · Shift+E绑定`:''} · 已通过 ${Math.max(0,t.detectorCount||0)} 次`);tone(430+t.detectorMode*90,.08,'square');saveGame();return;}if(t.shape==='whistle'){t.whistleOn=t.whistleOn===false;rebuildMesh();toast(t.whistleOn?'鸣笛轨已启用':'鸣笛轨已静音');tone(t.whistleOn?700:240,.08,'square');saveGame();return;}if(!trackTrain.placed){placeTrackTrain(t);return;}const near=Math.hypot(player.x-trackTrain.x,player.z-trackTrain.z)<3;if(near||trackTrain.pieceId===t.id){trackTrain.running=!trackTrain.running;if(!trackTrain.running)trackTrain.speed=0;updateTrackModeHud();toast(trackTrain.running?'🚂 小火车继续行驶':'🚂 小火车已停下');tone(trackTrain.running?610:260,.08,'square');saveGame();}else if(!trackTrain.running){placeTrackTrain(t);}else toast('小火车正在别处行驶 · 选中轨道按 X 可停车');}
  function trackTrainHotkey(){if(!canNetworkEdit()){toast('主机暂时关闭了轨道控制权限');return;}if(trackTrain.placed){trackTrain.running=!trackTrain.running;if(!trackTrain.running)trackTrain.speed=0;updateTrackModeHud();toast(trackTrain.running?'🚂 小火车继续行驶':'🚂 小火车已停下');tone(trackTrain.running?610:260,.08,'square');saveGame();return;}const hit=raycast(6),t=hit&&hit.type===37?findTrackPiece(...hit.block):nearestTrackPiece(7);if(t)placeTrackTrain(t);else toast('先铺一段轨道，再放上小火车');}
