  function pushTrackBox(data,t,x0,y0,z0,x1,y1,z1,color){const shade=[.78,.70,1.03,.55,.88,.82],a=-t.rot*Math.PI/2,cx=Math.cos(a),sn=Math.sin(a),center=trackCenter(t),px=center.x,pz=center.z;faces.forEach((f,fi)=>{const c=color.map(v=>Math.min(1,v*shade[fi]));f.v.forEach(v=>{const lx=x0+(x1-x0)*v[0],wy=t.y+y0+(y1-y0)*v[1],lz=z0+(z1-z0)*v[2];data.push(px+lx*cx-lz*sn,wy,pz+lx*sn+lz*cx,...c);});});}
