  const dailyLetters=[
    {title:'记得好好吃饭',body:`厨房的柜子里总该留一点吃的。要是忙着赶路，也别忘了在篝火边烤条鱼。

照顾好自己，不是停下冒险，而是为了走得更远。`},
    {title:'下雨的日子',body:`雨大的时候，就坐在门廊下听一会儿。很多烦恼和雨一样，落着落着，也就轻了。`},
    {title:'关于橘子',body:`橘子不喜欢被勉强抱起来，但它愿意跟着的人，一定让它觉得安心。替我摸摸它。`},
    {title:'路的两边',body:`走路时别只盯着目的地。河边的萤火虫、雪地上的脚印，还有陌生人留下的灯，都是旅程的一部分。`},
    {title:'冷的时候',body:`围巾在宝箱里。雪原的风很大，可冰屋里总能找到一点温暖。你会发现，有些路我也走过。`},
    {title:'家的样子',body:`房子可以变大，家具可以挪动，院子也会长满新的叶子。只要你愿意回来，它就一直是家。`},
    {title:'留一张空白纸',body:`旅行手记最后留了一张空白纸。不是因为故事写完了，而是因为接下来的部分，应该由你自己决定。`}
  ];
  const storyEntries=[
    {title:'归来的路',body:`很多年后，你又走上了这条林间小路。信封里只有一把旧钥匙，和奶奶熟悉的字迹。

“如果有一天你想回来，小屋会替我等你。”`,quote:'树长高了，路变远了，但门廊上的风铃还记得你的脚步。'},
    {title:'灯还亮着',body:`木门推开时，屋里没有灰尘，壁炉也还留着温度。桌上摆着两只杯子，像是有人一直相信你今天会回来。`,quote:'家不是从未离开的地方，而是无论走多远，仍愿意为你亮灯的地方。'},
    {title:'旅行手记',body:`书架深处夹着一本旅行手记。奶奶在地图上画了矿洞、河对岸的营地，还有遥远的雪原。最后一页写着：

“替我去看看吧，然后把故事带回来。”`,quote:'真正的地图，不只记录道路，也记录一个人曾经勇敢走过的方向。'},
    {title:'旧地图与围巾',body:`宝箱里没有金银，只有一张旧地图、一条暖和的围巾，以及几份为旅途准备的材料。地图角落画着三颗小小的星。`,quote:'最珍贵的宝藏，总是有人提前替你想到的寒冷、黑夜和孤单。'},
    {title:'橘子认出了你',body:`门廊边的橘猫没有逃走。它闻了闻你的手，轻轻叫了一声，然后像很久以前那样跟在你身后。`,quote:'有些朋友不会问你离开了多久，只会在你回来时，把位置重新留在你身边。'},
    {title:'山腹里的回声',body:`矿洞深处传来水滴声。墙上的铜矿仍闪着微光，像奶奶手记里夹着的那片旧夕阳。`,quote:'勇敢不是不害怕黑暗，而是知道身后有一盏灯，仍愿意往前一步。'},
    {title:'河对岸的灯',body:`远行者营地的灯笼还挂在梁下。桌边留着不同旅人的刻痕，每一道都指向同一个愿望：平安回家。`,quote:'陌生人留下的一点善意，也能在很多年后，成为另一个人的篝火。'},
    {title:'北境雪屋',body:`风雪掩住了来路，冰屋里却安静温暖。床边放着一只旧杯子，杯底刻着奶奶年轻时的名字。原来她也曾到过这里。`,quote:'你以为自己正在走一条新路，后来才发现，爱你的人曾悄悄走在前面。'},
    {title:'把星光带回家',body:`三颗星晶在桌上发出柔和的光。矿洞、营地和雪原的故事，也终于回到了小屋。

风从门廊吹进来，旅行手记翻到最后一页，那里多出了一行从未见过的字：

“欢迎回家。接下来的故事，由你来写。”`,quote:'小屋等待的从来不只是一个归人，而是你愿意带回来的整个世界。'}
  ];
