  function catBlocked(x,z){if(x<1||z<1||x>W-1||z>D-1)return true;for(const dx of [-.15,.15])for(const dz of [-.15,.15])if(!isSolidType(get(Math.floor(x+dx),0,Math.floor(z+dz))))return true;if(decorPointBlocked(x,1,z,.18))return true;for(const dx of [-.18,.18])for(const dz of [-.18,.18])if(isSolidType(get(Math.floor(x+dx),1,Math.floor(z+dz))))return true;return false;}
  function catDistance(){return Math.hypot(player.x-cat.x,player.z-cat.z);}
  function updateCat(dt){
    if(cat.ridingTrain){if(trackTrain.placed){const wagon=trainTrailPose(.92);cat.x=wagon.x;cat.z=wagon.z;cat.y=wagon.y+.62;cat.yaw=wagon.yaw;cat.pose='sit';cat.playTimer=0;return;}cat.ridingTrain=false;cat.y=1.01;}if(netConnected&&netRole==='guest')return;cat.y=1.01;cat.wander+=dt;cat.petCooldown=Math.max(0,cat.petCooldown-dt);let tx=8.4+Math.sin(cat.wander*.35)*1.8,tz=18.2+Math.cos(cat.wander*.27)*.7;
    if(cat.befriended){if(cat.mode==='play'&&cat.playTimer>0){cat.playTimer=Math.max(0,cat.playTimer-dt);const phase=(10-cat.playTimer)*1.45;cat.yarnCurrentX=cat.yarnX+Math.sin(phase)*1.15;cat.yarnCurrentZ=cat.yarnZ+Math.sin(phase*.63)*.85;tx=cat.yarnCurrentX;tz=cat.yarnCurrentZ;if(cat.playTimer<=0){cat.mode='follow';cat.affection=Math.min(5,cat.affection+1);checkCatBond();toast('橘子玩累了，开心地回到你身边');saveGame();}}else if(cat.mode==='home'){tx=7.5;tz=12.5;}else if(cat.mode==='stay'){tx=cat.stayX;tz=cat.stayZ;}else if(player.y<3.5){const night=worldTime>=19||worldTime<6;if(night&&isInHouse()){tx=7.5;tz=12.5;}else{tx=player.x-Math.sin(player.yaw)*1.25;tz=player.z+Math.cos(player.yaw)*1.25;}if(catDistance()>18&&!catBlocked(tx,tz)){cat.x=tx;cat.z=tz;}}}
    const dx=tx-cat.x,dz=tz-cat.z,dist=Math.hypot(dx,dz);if(dist>.45){cat.pose='walk';cat.yaw=Math.atan2(dx,-dz);const speed=(cat.befriended?1.45:.55)*dt,mx=dx/dist*speed,mz=dz/dist*speed;if(!catBlocked(cat.x+mx,cat.z))cat.x+=mx;if(!catBlocked(cat.x,cat.z+mz))cat.z+=mz;}
    else {const atBed=Math.hypot(cat.x-7.5,cat.z-12.5)<.8,night=worldTime>=19||worldTime<6;cat.pose=atBed&&night?'sleep':'sit';}
  }
  function updateCatPanel(){document.getElementById('catHearts').textContent='♥'.repeat(cat.affection)+'♡'.repeat(5-cat.affection);document.getElementById('catFishCount').textContent=materialCount(8);document.getElementById('catFeedBtn').disabled=materialCount(8)<=0||cat.affection>=5;document.getElementById('catPlayBtn').disabled=cat.playTimer>0;const trainBtn=document.getElementById('catTrainBtn');trainBtn.disabled=(!trackTrain.placed||!trackTrain.wagonCount)&&!cat.ridingTrain;trainBtn.textContent=cat.ridingTrain?'让橘子下车':'乘坐客车厢';const giftReady=cat.affection>=5&&dayCount>cat.giftDay;document.getElementById('catGiftBtn').disabled=!giftReady;document.getElementById('catGiftBtn').textContent=cat.affection<5?'亲密度满后解锁':giftReady?'领取礼物':'今日礼物已领取';document.getElementById('catStatus').textContent=cat.ridingTrain?'正在乘坐木质客车厢':cat.mode==='play'?'正在追毛线球':cat.mode==='follow'?'正在跟随':cat.mode==='stay'?'正在原地等待':'正在回小屋休息';document.querySelectorAll('[data-catmode]').forEach(b=>b.classList.toggle('active',b.dataset.catmode===cat.mode));}
  function openCatPanel(){if(!cat.befriended||catDistance()>2.2)return;stopMining();stopPlacing();paused=true;Object.keys(keys).forEach(k=>keys[k]=false);document.getElementById('catPanel').classList.remove('hidden');document.exitPointerLock?.();updateCatPanel();}
