  function claimCatGift(){if(cat.affection<5||dayCount<=cat.giftDay)return;const gifts=[{t:1,n:4,name:'草方块 ×4'},{t:2,n:3,name:'木板 ×3'},{t:8,n:1,name:'鲜鱼 ×1'},{t:3,n:2,name:'石头 ×2'}],g=gifts[dayCount%gifts.length];stock[g.t]=Math.min(itemCap(g.t),(stock[g.t]||0)+g.n);cat.giftDay=dayCount;updateInventory();updateCraftUI();updateCatPanel();burst('#ffd45c');catMessage(`橘子带回了礼物：${g.name}`);tone(880,.12,'sine');saveGame();}
  function toggleCatTrainRide(){if(!cat.befriended)return;if(cat.ridingTrain){cat.ridingTrain=false;cat.mode='follow';cat.y=1.01;toast('🐈 橘子跳下客车厢，回到你身边');}else{if(!trackTrain.placed||!trackTrain.wagonCount){catMessage('先为主列车保留至少一节客车厢');return;}cat.ridingTrain=true;cat.mode='follow';cat.playTimer=0;const wagon=trainTrailPose(.92);cat.x=wagon.x;cat.z=wagon.z;cat.y=wagon.y+.62;cat.yaw=wagon.yaw;toast('🐈 橘子坐上了客车厢顶，准备一起旅行');}updateCatPanel();if(netConnected){catCommandPendingUntil=performance.now()+2500;netSend({kind:'catRide',ridingTrain:cat.ridingTrain});}saveGame();setTimeout(()=>{if(!document.getElementById('catPanel').classList.contains('hidden'))closeCatPanel();},120);}
