  function interact(shifted=false){
    if(ridingTrain){leaveTrackTrain();return;}if(fishingState===2){catchFish();return;}if(fishingState===1){toast('耐心一点，留意浮标…');return;}const look=raycast(3.4);
    if(look&&look.type===8){if(look.block[0]===11&&look.block[2]===15&&mainDoorExists)useDoor();else togglePlacedDoor(findPlacedDoorByBlock(...look.block));return;}const openDoor=nearestOpenDoor();if(openDoor){togglePlacedDoor(openDoor);return;}const lookedTrack=look&&look.type===37?findTrackPiece(...look.block):null;if(lookedTrack?.shape==='detector'&&shifted){cycleDetectorTarget(lookedTrack);return;}if(lookedTrack&&['switch','signal','station','power','lantern','crossing','oneway','drawbridge','whistle','turntable','detector'].includes(lookedTrack.shape)){interactTrack(lookedTrack);return;}if(trackTrain.placed&&Math.hypot(player.x-trackTrain.x,player.z-trackTrain.z)<1.45){boardTrackTrain();return;}if(lookedTrack){interactTrack(lookedTrack);return;}if(look&&look.type===9){toggleBlockLight(look);return;}const decorLight=nearestDecorLight();if(decorLight){toggleDecorLight(decorLight);return;}
    if((look&&look.type===33)||(mailboxExists()&&mailboxDistance()<2.2)){openMailbox();return;}
    if((look&&look.type===29)||(ladderExists()&&ladderDistance()<1.65)){useLadder();return;}if(look&&look.type===24){readBookshelf();return;}if(fireplaceExists()&&fireplaceDistance()<2.35&&player.y<4){toggleFireplace();return;}
    if(chestDistance()<2.8&&isInHouse()){chestOpened?openStorage():useChest();return;}
    if(nearSleepSpot()){useBed();return;}
    if(gardenDistance()<3.4){harvestGarden();return;}
    if(sheepExists()&&sheepDistance()<3){petSheep();return;}
    if(doorDistance()<3.15){useDoor();return;}
    if(catDistance()<2.2&&player.y<3.5){petCat();return;}
    if(pondExists()&&fishingDistance(nearestFishingSpot())<5.2){openPondPanel();return;}
    toast('这里没有可互动的东西');
  }
