  function findPlacedDoorByBlock(x,y,z){return placedDoors.find(d=>d.x===x&&d.z===z&&(y===d.y||y===d.y+1));}
  function nearestOpenDoor(){let best=null,dist=2.6;for(const d of placedDoors)if(d.open&&Math.abs(player.y-d.y)<3){const n=Math.hypot(player.x-(d.x+.5),player.z-(d.z+.5));if(n<dist){dist=n;best=d;}}return best;}
