  function decorSnapshot(){return JSON.stringify({decorations:decorations.map(d=>({...d})),themes:[...decorFloorThemes],walls:[...decorWallThemes]});}
  function recordDecorHistory(){decorUndo.push(decorSnapshot());if(decorUndo.length>30)decorUndo.shift();decorRedo.length=0;decorClearArmed=false;}
  function restoreDecorSnapshot(raw){const parsed=JSON.parse(raw),arr=Array.isArray(parsed)?parsed:(parsed.decorations||[]);decorations.length=0;for(const d of arr)if(decorDefs[d.type])decorations.push({...d,scale:d.scale||1,ox:d.ox||0,oz:d.oz||0,elev:d.elev||0});if(!Array.isArray(parsed)&&Array.isArray(parsed.themes))decorFloorThemes=[parsed.themes[0]||0,parsed.themes[1]||0];if(!Array.isArray(parsed)&&Array.isArray(parsed.walls))decorWallThemes=[parsed.walls[0]||0,parsed.walls[1]||0];nextDecorId=Math.max(1,...decorations.map(d=>d.id+1));selectedDecorId=null;decorSelection.clear();decorTool=null;decorMoveMode=false;saveGame();updateDecorEditor();}
