  function nudgeDecor(dx,dz){applyDecorBatch(d=>{d.ox=Math.max(-.4,Math.min(.4,Math.round(((d.ox||0)+dx)*10)/10));d.oz=Math.max(-.4,Math.min(.4,Math.round(((d.oz||0)+dz)*10)/10));});}
